<?php
declare(strict_types=1); namespace Hls\Controllers;
use Hls\Http\View; use Hls\Http\Input; use Hls\Http\HttpError; use Hls\Repositories\Repository; use Hls\Middleware\Access; use Hls\Services\Audit;
final class FinanceReceivableController { public function __construct(private Repository $repo,private View $view,private Access $access,private Audit $audit){} private function scope():array{return [$this->access->user['id'],$this->access->user['all_branches']];}
 public function receivables():void{$this->access->demand('finance.receivable.view');$rows=$this->repo->all('SELECT i.*,c.name customer_name,b.name branch_name,COALESCE(SUM(CASE WHEN p.status="POSTED" THEN pa.amount ELSE 0 END),0) paid FROM fin_invoices i JOIN md_customers c ON c.id=i.customer_id JOIN branches b ON b.id=i.branch_id LEFT JOIN fin_payment_allocations pa ON pa.invoice_id=i.id LEFT JOIN fin_payments p ON p.id=pa.payment_id WHERE i.status IN ("ISSUED","PARTIALLY_PAID","PAID") AND i.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1) GROUP BY i.id ORDER BY i.due_date',$this->scope());$this->view->render('finance-receivables',['title'=>'Piutang','rows'=>$rows]);}
 public function payments():void{$this->access->demand('finance.payment.view');$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{if(($_POST['action']??'')==='reverse'){$this->access->demand('finance.payment.reverse');$pid=Input::id($_POST,'payment_id');$reason=trim((string)($_POST['reason']??''));if($reason==='')throw new HttpError(422,'Alasan reversal wajib diisi.');$this->repo->db->beginTransaction();$payment=$this->repo->one('SELECT * FROM fin_payments WHERE id=? FOR UPDATE',[$pid]);if(!$payment||!$this->access->branch((int)$payment['branch_id']))throw new HttpError(404,'Pembayaran tidak ditemukan.');if($payment['status']!=='POSTED')throw new HttpError(409,'Pembayaran sudah dibatalkan atau tidak dapat direversal.');$alloc=$this->repo->all('SELECT invoice_id FROM fin_payment_allocations WHERE payment_id=?',[$pid]);$this->repo->run('UPDATE fin_payments SET status="REVERSED",version=version+1,updated_at=NOW() WHERE id=? AND status="POSTED"',[$pid]);$this->repo->run('INSERT INTO fin_cash_ledger(branch_id,account_id,transaction_type,reference_type,reference_id,transaction_date,debit,credit,note,created_by,created_at) VALUES(?, ?,"REVERSAL","PAYMENT",?,?,0,?,?,?,NOW())',[$payment['branch_id'],$payment['account_id'],$pid,date('Y-m-d'),$payment['amount'],'Reversal: '. $reason,$this->access->user['id']]);foreach($alloc as $a){$sum=$this->repo->one('SELECT COALESCE(SUM(pa.amount),0) paid FROM fin_payment_allocations pa JOIN fin_payments p ON p.id=pa.payment_id WHERE pa.invoice_id=? AND p.status="POSTED"',[$a['invoice_id']]);$inv=$this->repo->one('SELECT total_amount FROM fin_invoices WHERE id=?',[$a['invoice_id']]);$paid=(float)$sum['paid'];$status=$paid<=0.0001?'ISSUED':($paid+0.0001>=(float)$inv['total_amount']?'PAID':'PARTIALLY_PAID');$this->repo->run('UPDATE fin_invoices SET status=?,version=version+1,updated_at=NOW() WHERE id=?',[$status,$a['invoice_id']]);}$this->repo->db->commit();$this->audit->record((int)$this->access->user['id'],'finance_payment_reversed','fin_payments',$pid,['reason'=>$reason,'amount'=>$payment['amount']]);$this->view->redirect('/finance/payments');}$this->access->demand('finance.payment.create');$account=Input::id($_POST,'account_id');$date=Input::text($_POST,'payment_date',10,false)?:date('Y-m-d');$ref=trim((string)($_POST['payment_ref']??''));$ids=$_POST['invoice_id']??[];$vals=$_POST['allocation']??[];if(!is_array($ids)||!is_array($vals)||count($ids)!==count($vals)||!$ids)throw new HttpError(422,'Pilih minimal satu invoice.');if($ref==='')$ref='PAY-'.bin2hex(random_bytes(8));$this->repo->db->beginTransaction();$acc=$this->repo->one('SELECT * FROM fin_accounts WHERE id=? AND active=1 FOR UPDATE',[$account]);if(!$acc||!$this->access->branch((int)$acc['branch_id']))throw new HttpError(422,'Rekening tidak tersedia.');$total=0;$customer=null;$branch=(int)$acc['branch_id'];$locked=[];foreach($ids as $k=>$invoice){$invoice=(int)$invoice;$amount=round((float)$vals[$k],2);if($amount<=0)throw new HttpError(422,'Nominal alokasi harus positif.');$row=$this->repo->one('SELECT i.*,COALESCE(SUM(CASE WHEN p.status="POSTED" THEN pa.amount ELSE 0 END),0) paid FROM fin_invoices i LEFT JOIN fin_payment_allocations pa ON pa.invoice_id=i.id LEFT JOIN fin_payments p ON p.id=pa.payment_id WHERE i.id=? AND i.status IN ("ISSUED","PARTIALLY_PAID") GROUP BY i.id FOR UPDATE',[$invoice]);if(!$row||!$this->access->branch((int)$row['branch_id'])||(int)$row['branch_id']!==$branch)throw new HttpError(422,'Invoice tidak tersedia dalam cakupan rekening.');if($customer!==null&&(int)$row['customer_id']!==$customer)throw new HttpError(422,'Semua invoice harus milik customer yang sama.');$customer=(int)$row['customer_id'];$remaining=round((float)$row['total_amount']-(float)$row['paid'],2);if($amount>$remaining)throw new HttpError(422,'Alokasi melebihi saldo piutang.');$total=round($total+$amount,2);$locked[]=[$row,$amount,$remaining];}if($total<=0)throw new HttpError(422,'Total pembayaran harus positif.');$this->repo->run('INSERT INTO fin_payments(branch_id,payment_ref,payment_date,account_id,amount,status,created_by,created_at,updated_at) VALUES(?,?,?,?,?,"POSTED",?,NOW(),NOW())',[$branch,$ref,$date,$account,$total,$this->access->user['id']]);$pid=(int)$this->repo->db->lastInsertId();foreach($locked as [$row,$amount,$remaining]){$this->repo->run('INSERT INTO fin_payment_allocations(payment_id,invoice_id,amount,created_at) VALUES(?,?,?,NOW())',[$pid,$row['id'],$amount]);$status=($remaining-$amount)<=0.0001?'PAID':'PARTIALLY_PAID';$this->repo->run('UPDATE fin_invoices SET status=?,version=version+1,updated_at=NOW() WHERE id=?',[$status,$row['id']]);}$this->repo->run('INSERT INTO fin_cash_ledger(branch_id,account_id,transaction_type,reference_type,reference_id,transaction_date,debit,credit,note,created_by,created_at) VALUES(?,?,"RECEIPT","PAYMENT",?,?,?,0,"Penerimaan pembayaran",?,NOW())',[$branch,$account,$pid,$date,$total,$this->access->user['id']]);$this->repo->db->commit();$this->audit->record((int)$this->access->user['id'],'finance_payment_posted','fin_payments',$pid,['allocations'=>count($locked),'amount'=>$total,'payment_ref'=>$ref]);$this->view->redirect('/finance/payments');}catch(HttpError $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();$error=$e->getMessage();}catch(\Throwable $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();if(str_contains($e->getMessage(),'Duplicate'))$error='Referensi pembayaran sudah digunakan.';else throw $e;}}$rows=$this->repo->all('SELECT p.*,a.code account_code,c.name customer_name,GROUP_CONCAT(i.official_number SEPARATOR ", ") official_number,SUM(pa.amount) allocated FROM fin_payments p JOIN fin_accounts a ON a.id=p.account_id JOIN fin_payment_allocations pa ON pa.payment_id=p.id JOIN fin_invoices i ON i.id=pa.invoice_id JOIN md_customers c ON c.id=i.customer_id WHERE p.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1) GROUP BY p.id ORDER BY p.id DESC',$this->scope());$invoices=$this->repo->all('SELECT i.id,i.official_number,i.total_amount,c.name customer_name,ROUND(i.total_amount-COALESCE((SELECT SUM(pa.amount) FROM fin_payment_allocations pa JOIN fin_payments p ON p.id=pa.payment_id WHERE pa.invoice_id=i.id AND p.status="POSTED"),0),2) remaining FROM fin_invoices i JOIN md_customers c ON c.id=i.customer_id WHERE i.status IN ("ISSUED","PARTIALLY_PAID") AND i.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1) ORDER BY i.id DESC',$this->scope());$accounts=$this->repo->all('SELECT id,branch_id,code,name FROM fin_accounts WHERE active=1 AND branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1)',$this->scope());$this->view->render('finance-payments',['title'=>'Pembayaran','invoices'=>$invoices,'accounts'=>$accounts,'rows'=>$rows,'error'=>$error]);}}